<script setup>
import {ref,computed,watch} from 'vue'
import {useRouter} from 'vue-router'
import {useIrrigation} from '../data/runtime.js'
import {useClock} from '../composables/useClock.js'
import {latestZoneReading} from '../composables/telemetryReadings.js'
import {projectFieldMap} from './fieldMapLayout.js'
import MetricCard from '../components/MetricCard.vue'
import StatusBadge from '../components/StatusBadge.vue'
import NavIcon from '../components/NavIcon.vue'
import {dateText,numberText,alarmStates,recovery} from './alarms/supportUi.js'
const r=useIrrigation(),router=useRouter(),clock=useClock(),date=ref(clock.isReference?'2026-07-28':clock.today.value),summary=ref(null),failure=ref(''),busy=ref(false)
let request=0
async function load(refresh=false){const token=++request;busy.value=true;failure.value='';try{if(refresh)await r.refresh();const result=await r.query('overview',{date:date.value,asOf:clock.displayNow.value.toISOString()});if(token===request)summary.value=result}catch(e){if(token===request){summary.value=null;failure.value=e.message}}finally{if(token===request)busy.value=false}}
watch(()=>[r.state.revision,date.value],()=>{if(r.state.user)load()},{immediate:true})
const get=(kind,id)=>r.getIndex().byId[kind]?.get(id),current=computed(()=>summary.value?.activeRuns[0]),queued=computed(()=>summary.value?.queuedRuns[0]),step=computed(()=>get('RunStep',current.value?.activeStepId)),zone=computed(()=>get('IrrigationZone',step.value?.zoneId)),alarm=computed(()=>summary.value?.alarmSummary),work=computed(()=>(r.state.entities.WorkOrder??[]).find(w=>w.alarmId===alarm.value?.alarmId))
function reading(kind){return latestZoneReading(r.state.entities,[zone.value?.zoneId],kind,clock.displayNow.value)}
function readText(kind,digits=1){const result=reading(kind);if(!result)return '无有效读数';if(result.stale)return '读数已过期';return numberText(result.reading.value,digits)}
const interim=computed(()=>{const meter=reading('METER_TOTAL');return meter&&!meter.stale&&Number.isFinite(step.value?.meterStart)&&Number(meter.reading.value)>=step.value.meterStart?numberText(Number(meter.reading.value)-step.value.meterStart):'—'})
const mapPageNumber=ref(1),authorizedFields=computed(()=>r.state.entities.Field??[]),mapProjection=computed(()=>projectFieldMap(authorizedFields.value,mapPageNumber.value)),mapFields=computed(()=>mapProjection.value.items)
watch(()=>mapProjection.value.page,page=>{if(page!==mapPageNumber.value)mapPageNumber.value=page})
const activeFields=computed(()=>new Set((r.state.entities.RunStep??[]).filter(s=>(summary.value?.activeRuns??[]).some(run=>run.runId===s.runId)&&s.status==='RUNNING').map(s=>get('IrrigationZone',s.zoneId)?.fieldId)))
const metrics=computed(()=>summary.value?[{label:'田块面积',value:numberText(summary.value.fieldAreaMu),unit:'亩',icon:'field',path:'/fields'},{label:'正在灌溉',value:summary.value.runningCount,unit:'任务',icon:'water',tone:'info',path:'/runs'},{label:'今日已结算用水',value:numberText(summary.value.settledWaterM3),unit:'m³',icon:'audit',tone:'info',path:'/water?start='+date.value+'&end='+date.value},{label:'待处理告警',value:summary.value.pendingAlarmCount,unit:'条',icon:'alarm',tone:'warning',path:'/alarms?status=NOT_CLOSED'},{label:'离线设备',value:summary.value.offlineDeviceCount,unit:'台',icon:'device',tone:'danger',path:'/devices?connection=OFFLINE'},{label:'设备在线率',value:summary.value.deviceOnlineRate===null?'无设备':numberText(summary.value.deviceOnlineRate,2)+'%',icon:'wifi',path:'/devices?connection=ONLINE'}]:[])
</script>
<template><div class="page-stack overview-page"><div class="overview-filters"><label class="filter-field">日期<input v-model="date" type="date"/></label><label class="filter-field">农场<select :value="r.state.user?.farmId"><option :value="r.state.user?.farmId">{{r.state.entities.Farm?.[0]?.name||r.state.publicFarm?.name}}</option></select></label><button class="btn refresh" :disabled="busy" @click="load(true)"><NavIcon name="refresh"/>刷新</button></div><p v-if="failure" role="alert" class="error-text">{{failure}} <button class="btn-link" @click="load(true)">重试</button></p><template v-if="summary"><div class="overview-metrics"><button v-for="m in metrics" :key="m.label" class="metric-trigger" :title="m.label==='今日已结算用水'?'所选日期有效结算水量':'当前授权范围的快照'" @click="router.push(m.path)"><MetricCard v-bind="m"/></button></div><div class="overview-main"><section class="panel map-panel"><h2 class="panel-title">田块态势</h2><nav v-if="mapProjection.pageCount>1" class="map-pagination" aria-label="田块态势翻页"><button class="btn btn-sm" aria-label="上一页田块" :disabled="mapProjection.page<=1" @click="mapPageNumber=mapProjection.page-1">上一页</button><span aria-live="polite">第 {{mapProjection.page}} / {{mapProjection.pageCount}} 页，共 {{mapProjection.total}} 个授权田块</span><button class="btn btn-sm" aria-label="下一页田块" :disabled="mapProjection.page>=mapProjection.pageCount" @click="mapPageNumber=mapProjection.page+1">下一页</button></nav><div class="north">北 <span>➤</span></div><svg viewBox="0 0 805 410" role="img" :aria-label="'农场田块示意图，共 '+mapProjection.total+' 个授权田块'"><defs><linearGradient id="fieldGreen"><stop stop-color="#bedfaa"/><stop offset="1" stop-color="#c6e8b6"/></linearGradient><linearGradient id="runningGreen"><stop stop-color="#54bc78"/><stop offset="1" stop-color="#2ab56e"/></linearGradient></defs><path d="M66 20L766 34L804 360L802 400L2 400L17 289Q-4 220 17 131Q29 70 66 20Z" fill="#e8edef"/><path d="M76 22Q10 92 20 184Q39 252 23 303L11 389L794 388L792 365L83 352L31 366L45 285Q63 248 42 177Q32 109 99 24Z" fill="#b2e8fa"/><text x="28" y="200" fill="#126d9b" font-size="15">河</text><text x="28" y="246" fill="#126d9b" font-size="15">流</text><text x="402" y="380" fill="#126d9b" font-size="15">南渠</text><g v-for="f in mapFields" :key="f.field.fieldId" class="field-polygon" role="link" tabindex="0" :data-field-id="f.field.fieldId" :aria-label="f.field.name+'，查看田块档案'" @click="router.push(f.path)" @keydown.enter.prevent="router.push(f.path)" @keydown.space.prevent="router.push(f.path)"><polygon :points="f.points" :fill="activeFields.has(f.field.fieldId)?'url(#runningGreen)':'url(#fieldGreen)'" stroke="white" stroke-width="2" stroke-linejoin="round"/><text :x="f.x" :y="f.y" :fill="activeFields.has(f.field.fieldId)?'white':'#17362b'" font-size="15" text-anchor="middle">{{f.field.name}}</text><path v-if="activeFields.has(f.field.fieldId)" :transform="'translate('+(f.x-9)+','+(f.y-45)+')'" d="M9 0Q-9 23 9 24Q27 23 9 0" fill="none" stroke="white" stroke-width="2.5"/></g></svg><p v-if="!mapFields.length" class="empty-state">没有可显示的田块。</p></section><div class="overview-tasks"><section class="panel current-task"><header><h2 class="panel-title">当前任务</h2><StatusBadge v-if="current" :status="current.status"/></header><dl v-if="current" class="task-pairs"><dt>运行编号</dt><dd><button class="btn-link" @click="router.push('/runs/'+current.runId)">{{current.runId}}</button></dd><dt>计划编号</dt><dd><button class="btn-link" @click="router.push('/plans/'+current.planId+'/edit')">{{current.planId}}</button></dd><dt>运行区域</dt><dd>{{zone?.name||'—'}}</dd><dt>开始时间</dt><dd>{{dateText(current.actualStartedAt)}}</dd><dt>目标用水量</dt><dd>{{numberText(step?.targetVolumeM3,0)}} m³</dd><dt>当前流量</dt><dd>{{readText('FLOW_RATE')}} m³/h</dd><dt>当前压力</dt><dd>{{readText('PRESSURE',2)}} MPa</dd><dt>暂计水量(未结算)</dt><dd>{{interim}} m³</dd></dl><p v-else class="empty-state">当前没有运行任务</p></section><section class="panel queued-task"><header><h2 class="panel-title">待执行任务</h2><StatusBadge v-if="queued" :status="queued.status"/></header><dl v-if="queued" class="task-pairs"><dt>运行编号</dt><dd><button class="btn-link" @click="router.push('/runs/'+queued.runId)">{{queued.runId}}</button></dd><dt>计划编号</dt><dd><button class="btn-link" @click="router.push('/plans/'+queued.planId+'/edit')">{{queued.planId}}</button></dd><dt>任务状态</dt><dd>待执行</dd></dl><p v-else class="empty-state">没有待执行任务</p></section></div></div><section class="panel overview-alarm"><h2 class="panel-title">告警摘要</h2><div v-if="alarm" class="alarm-summary"><span class="alarm-symbol"><NavIcon name="alarm" :size="40"/></span><dl class="task-pairs"><dt>告警编号</dt><dd><button class="btn-link" @click="router.push({path:'/alarms',query:{selected:alarm.alarmId}})">{{alarm.alarmId}}</button></dd><dt>告警名称</dt><dd>{{get('Device',alarm.deviceId)?.name||'—'}}</dd><dt>关联设备</dt><dd><button class="btn-link" @click="router.push('/devices/'+alarm.deviceId)">{{alarm.deviceId}}</button></dd><dt>告警状态</dt><dd><StatusBadge :status="alarm.status" :text="alarmStates[alarm.status]"/></dd></dl><dl class="task-pairs"><dt>恢复状态</dt><dd><StatusBadge :status="alarm.recovery" :text="recovery[alarm.recovery]" :tone="alarm.recovery==='ACTIVE'?'danger':'success'"/></dd><dt>发生时间</dt><dd>{{dateText(alarm.openedAt)}}</dd><dt>工单编号</dt><dd><button v-if="work" class="btn-link" @click="router.push({path:'/maintenance',query:{selected:work.workOrderId}})">{{work.workOrderId}}</button><span v-else>—</span></dd><dt>指派人员</dt><dd>{{get('User',work?.assigneeId)?.name||'—'}}</dd></dl><dl class="task-pairs"><dt>工单状态</dt><dd><StatusBadge v-if="work" :status="work.status"/><span v-else>—</span></dd></dl></div><p v-else class="empty-state">当前没有待处理告警</p></section></template><p v-else-if="busy" class="empty-state">正在读取总览…</p></div></template>
<style scoped>.overview-page{gap:20px}.overview-filters{display:flex;gap:15px;align-items:center;height:40px;padding-left:6px}.overview-filters .filter-field{flex:none;min-width:0;width:282px;white-space:nowrap;flex-direction:row;align-items:center;gap:16px}.overview-filters .filter-field>span{flex:none;white-space:nowrap}.overview-filters input,.overview-filters select{width:230px;flex:none;height:47px}.refresh{margin-left:auto;height:46px;display:flex;gap:12px;align-items:center;color:#098b4c;min-width:112px;justify-content:center}.overview-metrics{display:grid;grid-template-columns:repeat(6,1fr);gap:9px}.metric-trigger{padding:0;border:0;background:none;text-align:left;cursor:pointer;min-width:0}.overview-metrics :deep(.metric-card){height:119px;align-items:flex-start;padding:18px 19px;gap:17px}.overview-metrics :deep(.metric-label){white-space:nowrap;font-size:14px}.overview-metrics :deep(.metric-number){font-size:29px;line-height:1.4}.overview-metrics :deep(.metric-unit){display:block;font-size:15px;margin:0}.overview-metrics :deep(.metric-icon){min-width:52px;height:52px}.overview-main{display:grid;grid-template-columns:2.15fr 1fr;gap:20px;height:486px}.map-panel{position:relative;padding:15px 21px;overflow:hidden}.map-panel svg{width:100%;height:420px;margin-top:4px}.map-pagination{position:absolute;z-index:1;top:13px;right:78px;display:flex;align-items:center;gap:9px;margin:0;font-size:12px;color:#607974}.map-pagination .btn-sm{padding:4px 11px}.north{position:absolute;right:31px;top:15px;font-size:14px;display:flex;flex-direction:column;text-align:center}.north span{transform:rotate(-90deg);font-size:25px;color:#008349}.field-polygon{cursor:pointer}.field-polygon:hover polygon,.field-polygon:focus polygon{stroke:#0c8659;stroke-width:3}.overview-tasks{display:flex;flex-direction:column;gap:18px}.current-task,.queued-task{padding:14px 20px}.current-task{height:310px}.queued-task{flex:1}.overview-tasks header{display:flex;align-items:center;justify-content:space-between;margin-bottom:17px}.task-pairs{display:grid;grid-template-columns:118px 1fr;gap:7px 9px;font-size:15px;margin:0}.task-pairs dt{color:#607974;white-space:nowrap}.task-pairs dd{margin:0;white-space:nowrap}.task-pairs .btn-link{font-size:15px;color:#20342f}.overview-alarm{height:198px;padding:14px 21px}.alarm-summary{display:grid;grid-template-columns:112px 1.28fr 1.1fr .7fr;gap:22px;margin-top:12px}.alarm-summary .task-pairs{grid-template-columns:145px 1fr}.alarm-summary .task-pairs:last-child{grid-template-columns:105px 1fr}.alarm-symbol{width:85px;height:85px;display:grid;place-items:center;background:#ffe3e5;border-radius:50%;color:#bd001c}.overview-page .panel-title{font-size:20px}
</style>
